INSERT INTO content_versions(id,catalog) VALUES ('2026.10.1', '{"version":"2026.10.1","lessons":[{"id":"decomposition","name":"Decomposition","title":"การแยกย่อยปัญหา","zone":"ป่าแห่งการเริ่มต้น","objective":"แบ่งปัญหาใหญ่เป็นงานย่อยที่ช่วยให้ลงมือทำได้ และอธิบายได้ว่าแต่ละงานช่วยอย่างไร","challenge":"หลังพักกลางวัน ห้องเรียนเต็มไปด้วยขยะ! ทีมพิทักษ์โรงเรียนจะเริ่มแก้ตรงไหนก่อนดี?","explanation":"ปัญหาใหญ่เหมือนกระเป๋าใบโต ลองหยิบงานออกมาทีละชิ้น เราจะเห็นว่าใครทำอะไรได้บ้าง งานย่อยต้องช่วยให้ถึงเป้าหมายเดิมนะ","examples":[{"title":"จัดงานกีฬาสี","steps":["เป้าหมาย: ทุกทีมแข่งขันอย่างพร้อมเพรียง","แบ่งเป็น จัดสนาม • เตรียมอุปกรณ์ • แบ่งทีม • จัดตาราง • เตรียมน้ำ","มอบหมายแต่ละทีม แล้วตรวจว่างานใดต้องรออีกงาน"]},{"title":"ลดขยะในห้องเรียน","steps":["เป้าหมาย: ขยะลดลงและทิ้งถูกถัง","สำรวจชนิดขยะและจุดที่พบ • ตรวจจำนวนถัง • คิดวิธีลดขยะ • ติดตามผล","เริ่มจากสำรวจหนึ่งวัน แล้วใช้ข้อมูลวางงานถัดไป"]}],"game":{"type":"select","prompt":"เลือกงานย่อยที่ช่วยจัดการขยะในห้องเรียน (เลือกได้หลายข้อ)","items":["สำรวจว่ามีขยะชนิดใด","นับถังขยะและดูตำแหน่ง","ทายสีรองเท้าของเพื่อน","แบ่งหน้าที่เก็บและแยกขยะ","ตั้งชื่อดาวดวงใหม่"],"correct":[0,1,3],"feedback":"งานย่อยที่ดีช่วยให้รู้ปัญหา วางแผน หรือลงมือแก้ขยะ ลองตรวจว่าแต่ละการ์ดช่วยเป้าหมายนี้หรือไม่"},"guided":"ถ้าจะจัดกีฬาสี แบ่งงานอย่างน้อย 3 ส่วน แล้วบอกว่าแต่ละส่วนทำอะไร","independent":"ห้องสมุดมีหนังสือวางปนกัน แบ่งปัญหาเป็นงานย่อยที่ทีมของเธอทำได้ พร้อมเหตุผล","reflection":"งานใหญ่ข้อไหนดูง่ายขึ้นเมื่อแบ่งเป็นส่วนเล็ก ๆ? ครั้งหน้าจะลองแบ่งอย่างไร?","hints":["เป้าหมายคืออะไร และมีงานอะไรที่ต้องทำเพื่อไปถึงเป้าหมายนั้น?","ลองแยกตาม คน สถานที่ และอุปกรณ์ มีอะไรต้องเตรียมบ้าง?","งานย่อยหนึ่งคือเตรียมสนามให้พร้อม ลองหางานย่อยอีกสองอย่างที่ไม่ซ้ำกัน"],"quiz":[{"id":"decomposition-1","skill":"decomposition","concept":"งานย่อยตรงเป้าหมาย","prompt":"จะจัดกีฬาสี งานใดช่วยให้งานเริ่มได้?","options":["เลือกชื่อดวงดาว","จัดสนามและอุปกรณ์","นับสีรองเท้า"],"correct":1,"feedback":["ลองคิดอีกครั้ง: สนามและอุปกรณ์เป็นส่วนหนึ่งที่ต้องเตรียมสำหรับการแข่งขัน","ใช่เลย! สนามและอุปกรณ์เป็นส่วนหนึ่งที่ต้องเตรียมสำหรับการแข่งขัน","ลองคิดอีกครั้ง: สนามและอุปกรณ์เป็นส่วนหนึ่งที่ต้องเตรียมสำหรับการแข่งขัน"]},{"id":"decomposition-2","skill":"decomposition","concept":"แบ่งงาน","prompt":"ห้องสมุดรก ควรเริ่มอย่างไร?","options":["แบ่งเป็นรวบรวม แยกหมวด และจัดชั้น","บอกว่าเก็บทั้งหมดเลย","รอให้ห้องเรียบร้อยเอง"],"correct":0,"feedback":["ใช่เลย! งานที่แยกชัดเจนทำให้เริ่มทีละส่วนและแบ่งหน้าที่ได้","ลองคิดอีกครั้ง: งานที่แยกชัดเจนทำให้เริ่มทีละส่วนและแบ่งหน้าที่ได้","ลองคิดอีกครั้ง: งานที่แยกชัดเจนทำให้เริ่มทีละส่วนและแบ่งหน้าที่ได้"]},{"id":"decomposition-3","skill":"decomposition","concept":"ขอบเขตงาน","prompt":"ข้อใดเป็นงานย่อยที่ลงมือทำได้?","options":["ทำให้ทุกอย่างดี","แก้ปัญหาทั้งโรงเรียน","นับถังขยะในแต่ละอาคาร"],"correct":2,"feedback":["ลองคิดอีกครั้ง: การนับถังมีขอบเขตและผลลัพธ์ชัดเจน","ลองคิดอีกครั้ง: การนับถังมีขอบเขตและผลลัพธ์ชัดเจน","ใช่เลย! การนับถังมีขอบเขตและผลลัพธ์ชัดเจน"]},{"id":"decomposition-4","skill":"decomposition","concept":"งานที่ยังขาด","prompt":"เตรียมสนามและแบ่งทีมแล้ว แต่ผู้เล่นกระหายน้ำ ขาดงานใด?","options":["เตรียมน้ำดื่ม","เปลี่ยนชื่อทีม","วาดดาว"],"correct":0,"feedback":["ใช่เลย! ตรวจงานย่อยที่ยังขาดให้สอดคล้องกับความต้องการจริง","ลองคิดอีกครั้ง: ตรวจงานย่อยที่ยังขาดให้สอดคล้องกับความต้องการจริง","ลองคิดอีกครั้ง: ตรวจงานย่อยที่ยังขาดให้สอดคล้องกับความต้องการจริง"]},{"id":"decomposition-5","skill":"decomposition","concept":"เชื่อมงานย่อย","prompt":"สำรวจขยะแล้วควรนำผลไปทำอะไร?","options":["เก็บข้อมูลไว้เฉย ๆ","ใช้วางแผนจุดตั้งถัง","เลือกสีรองเท้า"],"correct":1,"feedback":["ลองคิดอีกครั้ง: งานย่อยควรเชื่อมกันเพื่อแก้เป้าหมายใหญ่","ใช่เลย! งานย่อยควรเชื่อมกันเพื่อแก้เป้าหมายใหญ่","ลองคิดอีกครั้ง: งานย่อยควรเชื่อมกันเพื่อแก้เป้าหมายใหญ่"]}]},{"id":"pattern","name":"Pattern Recognition","title":"การหารูปแบบ","zone":"หุบเขานักสืบ","objective":"บอกรูปแบบจากข้อมูลหลายวัน พร้อมยกหลักฐานและเลือกการลงมือทำที่เหมาะสม","challenge":"ทีมสำรวจเก็บข้อมูลขยะได้ 5 วัน ลองเป็นนักสืบว่าขยะชนิดใดเกิดซ้ำมากที่สุด","explanation":"รูปแบบคือสิ่งที่คล้ายกัน เกิดซ้ำ หรือเปลี่ยนไปในทิศทางหนึ่ง เราต้องดูหลายข้อมูล และบอกได้ว่าดูจากตรงไหน อย่าเดาว่าพรุ่งนี้จะเหมือนเดิมแน่นอน","examples":[{"title":"ขยะโรงอาหาร 5 วัน (หน่วย: ถุงขนาดเท่ากัน)","steps":["จันทร์: พลาสติก 8 กระดาษ 3 เศษอาหาร 12","อังคาร: 7 / 2 / 13 • พุธ: 9 / 4 / 14","พฤหัสบดี: 8 / 3 / 12 • ศุกร์: 10 / 3 / 15","เศษอาหารมากที่สุดทุกวัน จึงทดลองลดอาหารเหลือ แล้ววัดผลอีกครั้ง"]},{"title":"อุปกรณ์กีฬาหายบ่อย","steps":["จันทร์ พุธ ศุกร์ ลูกบอลถูกวางนอกตู้หลังใช้","รูปแบบ: ของไม่ได้กลับที่เดิมหลังจบกิจกรรม","ลองติดป้ายที่เก็บและตรวจทุกครั้งหลังใช้ ไม่กล่าวโทษใครจากการเดา"]}],"game":{"type":"select","prompt":"จากข้อมูล 5 วัน ข้อสรุปใดมีหลักฐานรองรับ?","items":["เศษอาหารมากกว่ากระดาษทุกวัน","พลาสติกเพิ่มขึ้นทุกวัน","เศษอาหารมากที่สุดทุกวัน","พรุ่งนี้ไม่มีขยะแน่นอน"],"correct":[0,2],"feedback":"ตรวจแต่ละวันในตาราง โดยเฉพาะคำว่า “ทุกวัน” และแยกสิ่งที่เห็นออกจากสิ่งที่คาดเดา"},"guided":"ใช้ข้อมูล 5 วัน บอกรูปแบบหนึ่งอย่าง อ้างตัวเลขอย่างน้อย 2 วัน และเสนอสิ่งที่จะทดลอง","independent":"ขวดน้ำที่ลืม: จันทร์ 2 อังคาร 5 พุธ 2 พฤหัสบดี 5 ศุกร์ 2 เห็นรูปแบบอะไร? ควรเก็บข้อมูลเพิ่มอย่างไรก่อนสรุปสาเหตุ?","reflection":"มีข้อสรุปไหนที่เธอเปลี่ยนใจหลังดูข้อมูลครบทุกวัน?","hints":["ข้อมูลส่วนใดซ้ำกัน และส่วนใดเปลี่ยนไป?","ลองเปรียบเทียบขยะชนิดเดียวกันอย่างน้อยสองวัน แล้วตรวจวันอื่นด้วย","จันทร์เศษอาหาร 12 ถุง มากกว่ากระดาษ 3 ถุง ลองตรวจอีกสองวันด้วยตัวเอง"],"quiz":[{"id":"pattern-1","skill":"pattern","concept":"หลักฐานจากหลายวัน","prompt":"เศษอาหาร 12,13,14,12,15 ถุง สรุปอย่างไร?","options":["เพิ่มทุกวัน","มีค่า 12 ซ้ำสองวัน","ลดทุกวัน"],"correct":1,"feedback":["ลองคิดอีกครั้ง: 12 ปรากฏวันแรกและวันที่สี่ แต่ข้อมูลไม่ได้เพิ่มทุกวัน","ใช่เลย! 12 ปรากฏวันแรกและวันที่สี่ แต่ข้อมูลไม่ได้เพิ่มทุกวัน","ลองคิดอีกครั้ง: 12 ปรากฏวันแรกและวันที่สี่ แต่ข้อมูลไม่ได้เพิ่มทุกวัน"]},{"id":"pattern-2","skill":"pattern","concept":"หลักฐานเปรียบเทียบ","prompt":"กระดาษ 3,2,4 และเศษอาหาร 12,13,14 ในสามวัน ข้อใดจริง?","options":["กระดาษมากกว่า","เท่ากันทุกวัน","เศษอาหารมากกว่าทั้งสามวัน"],"correct":2,"feedback":["ลองคิดอีกครั้ง: เปรียบเทียบชนิดขยะในวันเดียวกันทั้งสามวัน","ลองคิดอีกครั้ง: เปรียบเทียบชนิดขยะในวันเดียวกันทั้งสามวัน","ใช่เลย! เปรียบเทียบชนิดขยะในวันเดียวกันทั้งสามวัน"]},{"id":"pattern-3","skill":"pattern","concept":"การคาดการณ์","prompt":"เมื่อเศษอาหารมากที่สุด 5 วัน เรารู้สิ่งใดแน่นอน?","options":["ข้อมูล 5 วันนี้มีเศษอาหารมากที่สุด","ทุกวันในอนาคตจะเหมือนเดิม","เด็กทุกคนกินเหลือ"],"correct":0,"feedback":["ใช่เลย! ข้อสรุปต้องอยู่ในขอบเขตข้อมูลที่เก็บได้","ลองคิดอีกครั้ง: ข้อสรุปต้องอยู่ในขอบเขตข้อมูลที่เก็บได้","ลองคิดอีกครั้ง: ข้อสรุปต้องอยู่ในขอบเขตข้อมูลที่เก็บได้"]},{"id":"pattern-4","skill":"pattern","concept":"ใช้รูปแบบ","prompt":"ถ้าพบอาหารเหลือมากซ้ำ ๆ ควรทดลองอะไร?","options":["ทาสีประตู","ตักพอดีแล้วเพิ่มได้ และวัดอาหารเหลือ","หยุดเก็บข้อมูล"],"correct":1,"feedback":["ลองคิดอีกครั้ง: ใช้รูปแบบเลือกการทดลองที่สัมพันธ์กับปัญหาและติดตามผล","ใช่เลย! ใช้รูปแบบเลือกการทดลองที่สัมพันธ์กับปัญหาและติดตามผล","ลองคิดอีกครั้ง: ใช้รูปแบบเลือกการทดลองที่สัมพันธ์กับปัญหาและติดตามผล"]},{"id":"pattern-5","skill":"pattern","concept":"ตรวจสาเหตุ","prompt":"พบขยะมากวันศุกร์หนึ่งครั้ง ควรทำอย่างไร?","options":["สรุปว่าทุกศุกร์มาก","โทษคนใดคนหนึ่ง","เก็บข้อมูลเพิ่มหลายสัปดาห์"],"correct":2,"feedback":["ลองคิดอีกครั้ง: ข้อมูลครั้งเดียวอาจเป็นเหตุการณ์พิเศษ ต้องตรวจเพิ่ม","ลองคิดอีกครั้ง: ข้อมูลครั้งเดียวอาจเป็นเหตุการณ์พิเศษ ต้องตรวจเพิ่ม","ใช่เลย! ข้อมูลครั้งเดียวอาจเป็นเหตุการณ์พิเศษ ต้องตรวจเพิ่ม"]}]},{"id":"abstraction","name":"Abstraction","title":"การคิดเชิงนามธรรม","zone":"เกาะแห่งสิ่งสำคัญ","objective":"เลือกข้อมูลที่เกี่ยวข้องกับเป้าหมาย และอธิบายได้ว่าทำไมจึงเก็บหรือละข้อมูลนั้น","challenge":"เราจะเลือกถังขยะให้พอกับห้องเรียน แต่มีข้อมูลเต็มไปหมด อะไรจำเป็นจริง ๆ?","explanation":"คิดถึงเป้าหมายก่อน แล้วเก็บรายละเอียดที่ช่วยตัดสินใจ ข้อมูลที่ไม่ใช้ตอนนี้ไม่ได้ไร้ค่าเสมอไป ถ้าเป้าหมายเปลี่ยน สิ่งสำคัญก็อาจเปลี่ยนด้วย","examples":[{"title":"เลือกถังขยะ","steps":["เป้าหมาย: เลือกชนิดและความจุให้พอ","เก็บ: ชนิดขยะ ปริมาณต่อวัน ความจุถัง","ละ: สีรองเท้า อาหารที่ครูชอบ เพราะไม่ช่วยคำนวณถัง"]},{"title":"วาดแผนที่ไปห้องพยาบาล","steps":["เก็บ: จุดเริ่ม ทางเลี้ยว บันได และห้องพยาบาล","ละ: สีดินสอในกระเป๋าและชื่อขนมที่ขาย","ใช้สัญลักษณ์แทนสถานที่ เพื่อให้แผนที่อ่านง่าย"]}],"game":{"type":"select","prompt":"เก็บข้อมูลที่จำเป็นต่อการเลือกชนิดและขนาดถังขยะ ส่วนที่ไม่เลือกคือ “ละไว้ก่อน”","items":["ประเภทขยะ","ปริมาณขยะต่อวัน","สีรองเท้า","ความจุถัง","อาหารที่ครูชอบ"],"correct":[0,1,3],"feedback":"ถามว่า ถ้ารู้ข้อมูลนี้ เราจะเลือกชนิดหรือขนาดถังได้ดีขึ้นหรือไม่ แล้วอธิบายหนึ่งตัวเลือก"},"guided":"เลือกข้อมูลที่ควรเก็บเพื่อเลือกถังขยะ 3 อย่าง และอธิบายเหตุผลที่ละข้อมูลอีก 1 อย่าง","independent":"จะวางแผนเส้นทางจากประตูโรงเรียนถึงห้องสมุด ข้อมูลใดต้องรู้ และข้อมูลใดละได้? อธิบายเหตุผล","reflection":"เมื่อเป้าหมายเปลี่ยน ข้อมูลที่เคยละอาจสำคัญขึ้นได้อย่างไร?","hints":["เรากำลังตัดสินใจเรื่องอะไร?","ข้อมูลใดช่วยเลือกชนิดหรือขนาดถังได้โดยตรง?","ความจุถังช่วยบอกว่ารองรับขยะพอหรือไม่ ลองอธิบายอีกหนึ่งข้อมูลที่เธอเลือก"],"quiz":[{"id":"abstraction-1","skill":"abstraction","concept":"ข้อมูลตรงเป้าหมาย","prompt":"เลือกขนาดถัง ควรรู้สิ่งใด?","options":["สีรองเท้า","ปริมาณขยะต่อวัน","ชื่อสัตว์เลี้ยง"],"correct":1,"feedback":["ลองคิดอีกครั้ง: ปริมาณขยะใช้เทียบกับความจุถังได้","ใช่เลย! ปริมาณขยะใช้เทียบกับความจุถังได้","ลองคิดอีกครั้ง: ปริมาณขยะใช้เทียบกับความจุถังได้"]},{"id":"abstraction-2","skill":"abstraction","concept":"ละรายละเอียด","prompt":"วาดทางไปห้องสมุด ละข้อมูลใดได้?","options":["จุดเลี้ยว","ประตูทางเข้า","อาหารโปรดของเพื่อน"],"correct":2,"feedback":["ลองคิดอีกครั้ง: อาหารโปรดไม่ช่วยบอกเส้นทาง","ลองคิดอีกครั้ง: อาหารโปรดไม่ช่วยบอกเส้นทาง","ใช่เลย! อาหารโปรดไม่ช่วยบอกเส้นทาง"]},{"id":"abstraction-3","skill":"abstraction","concept":"เป้าหมายเปลี่ยน","prompt":"ถ้าจะซื้อรองเท้าทีม สีรองเท้าจะเป็นอย่างไร?","options":["อาจสำคัญต่อเป้าหมายใหม่นี้","ไม่สำคัญตลอดไป","ใช้เลือกถังขยะได้เสมอ"],"correct":0,"feedback":["ใช่เลย! ความเกี่ยวข้องขึ้นอยู่กับเป้าหมาย","ลองคิดอีกครั้ง: ความเกี่ยวข้องขึ้นอยู่กับเ